stories.push(...[{"id": "library", "title": "Der blaue Zettel", "level": "Einstieg · Mehrere Hinweise miteinander verbinden", "paragraphs": ["Am Samstagmorgen halfen Minka und Fuji in der kleinen Gartenbücherei. Unter einem Vordach stand ein Regal, aus dem Besucher Bücher ausleihen konnten. Jedes ausgeliehene Buch sollte in eine Liste eingetragen werden. Heute wollten die beiden das Regal ordnen. Zwischen zwei dicken Büchern lag ein zusammengefalteter blauer Zettel.", "Minka faltete ihn auf. „Ich suche das Buch mit dem Fuchs. Ich weiß den Titel nicht mehr. Es hat einen grünen Einband“, stand darauf. Darunter war ein kleiner Stern gezeichnet. „Wir nehmen einfach ein grünes Buch“, meinte Minka. Fuji schaute auf die Reihe. Vier Bücher hatten grüne Einbände.", "Im ersten Buch gab es nur Pflanzenbilder. Im zweiten erzählte eine Maus von ihrem Wintervorrat. Auf dem dritten stand „Der Fuchs und das verlorene Licht“. Minka zog es heraus. Auf der ersten Seite entdeckte sie denselben kleinen Stern wie auf dem Zettel. „Das könnte passen“, sagte Fuji.", "Doch das Buch hatte eine eingerissene Seite. Minka wollte es sofort ins Regal zurückschieben. Fuji hielt sie auf. „Wenn es noch mehr einreißt, fehlt nachher ein Stück Geschichte.“ Gemeinsam brachten sie das Buch zu Frau Weber, die sich um die Bücherei kümmerte. Sie befestigte den Riss mit einem geeigneten Reparaturstreifen.", "Kurz darauf kam ein Junge mit einem grünen Rucksack. Er suchte erst im Regal und dann neben der Liste. Minka zeigte ihm den Zettel. „Den habe ich geschrieben“, sagte er. Als er den Stern im Buch sah, strahlte er. „Genau das! Den Stern habe ich beim letzten Mal selbst hineingezeichnet.“", "Der Junge trug den Titel in die Ausleihliste ein und nahm das Buch mit. Minka räumte die anderen grünen Bücher an ihren Platz. „Nur die Farbe hätte nicht gereicht“, sagte sie. Fuji nickte. Auf den blauen Zettel schrieb Frau Weber noch den Buchtitel. Jetzt musste der Junge ihn nicht mehr erraten."], "questions": [{"type": "choice", "skill": "Informationen finden", "title": "Was wollen Minka und Fuji an diesem Morgen tun?", "choices": ["Das Regal ordnen.", "Den Rucksack reparieren.", "Einen Fuchs im Garten suchen."], "answer": 0, "ref": [1], "explain": "Ihr Auftrag am Morgen ist das Ordnen des Bücherregals.", "hint": "Suche ihre geplante Aufgabe vor dem Fund des Zettels."}, {"type": "choice", "skill": "Informationen finden", "title": "Welche zwei Hinweise zum Buch stehen auf dem blauen Zettel?", "choices": ["Ein roter Einband und ein Hund.", "Ein grüner Einband und ein Fuchs.", "Ein blauer Einband und eine Maus."], "answer": 1, "ref": [2], "explain": "Der Zettel nennt den Fuchs und den grünen Einband.", "hint": "Lies den Inhalt des Zettels. Seine eigene Farbe ist nicht die Buchfarbe."}, {"type": "choice", "skill": "Wörter aus dem Zusammenhang verstehen", "title": "Was ist hier mit „Einband“ gemeint?", "choices": ["Eine Schleife im Haar.", "Ein Band zum Reparieren.", "Die äußere Hülle des Buches."], "answer": 2, "ref": [2, 3], "explain": "Die grünen Einbände sind die äußeren Buchhüllen.", "hint": "Die beiden können die Farbe sehen, bevor sie die Bücher öffnen."}, {"type": "choice", "skill": "Ursachen erklären", "title": "Warum reicht es nicht, irgendein grünes Buch zu nehmen?", "choices": ["Vier Bücher sind grün, aber nicht alle handeln von einem Fuchs.", "Alle grünen Bücher sind ausgeliehen.", "Grüne Bücher dürfen nie ausgeliehen werden."], "answer": 0, "ref": [2, 3], "explain": "Vier Bücher haben die gesuchte Farbe. Erst weitere Hinweise grenzen das richtige Buch ein.", "hint": "Wie viele grüne Bücher stehen im Regal? Haben sie denselben Inhalt?"}, {"type": "choice", "skill": "Informationen finden", "title": "Welchen weiteren Hinweis entdecken die beiden im dritten Buch?", "choices": ["Einen grünen Rucksack.", "Denselben kleinen Stern wie auf dem Zettel.", "Eine Ausleihliste im Einband."], "answer": 1, "ref": [3], "explain": "Der Stern im Buch stimmt mit der Zeichnung auf dem Zettel überein.", "hint": "Suche den Hinweis auf der ersten Buchseite."}, {"type": "choice", "skill": "Bezüge verstehen", "title": "In Absatz 4 sagt Fuji: „Wenn es noch mehr einreißt …“ Was könnte noch mehr einreißen?", "choices": ["Der Rucksack.", "Der Zettel.", "Das Buch an seiner beschädigten Seite."], "answer": 2, "ref": [4], "explain": "Fuji spricht über den Riss an der Buchseite.", "hint": "Welcher Gegenstand ist im vorherigen Satz beschädigt?"}, {"type": "choice", "skill": "Aussagen prüfen", "title": "„Der Junge hat den Stern ins Buch gezeichnet.“ Welche Antwort passt?", "choices": ["Das steht im Text.", "Der Text sagt das Gegenteil.", "Dazu gibt es keine Information."], "answer": 0, "ref": [5], "explain": "Der Junge sagt ausdrücklich, dass er den Stern beim letzten Mal hineingezeichnet hat.", "hint": "Suche die Aussage des Jungen über den Stern."}, {"type": "order", "skill": "Ereignisse ordnen", "title": "Was geschieht zuerst? Ordne die vier Ereignisse.", "items": ["Der Junge leiht das Buch aus.", "Minka findet den blauen Zettel.", "Frau Weber repariert die eingerissene Seite.", "Minka entdeckt den Stern im dritten Buch."], "answer": [1, 3, 2, 0], "ref": [1, 3, 4, 6], "explain": "Die Ereignisse stehen nun so wie in der Geschichte: vom ersten bis zum letzten.", "hint": "Suche das Ereignis am Anfang. Was geschieht erst danach?"}, {"type": "choice", "skill": "Gefühle erkennen", "title": "Woran erkennt man, dass sich der Junge über das passende Buch freut?", "choices": ["Er trägt einen grünen Rucksack.", "Er strahlt, als er den Stern sieht.", "Er sucht neben der Liste."], "answer": 1, "ref": [5], "explain": "Sein Strahlen ist die Reaktion auf das Wiedererkennen des Buches.", "hint": "Suche seine Reaktion, nachdem er den Stern erkennt."}, {"type": "choice", "skill": "Die ganze Geschichte verstehen", "title": "Welche Zusammenfassung passt?", "choices": ["Minka sucht im Garten einen echten Fuchs und findet einen Stern.", "Fuji versteckt alle grünen Bücher vor einem Jungen.", "Die beiden finden mithilfe mehrerer Hinweise ein gesuchtes Buch, lassen es reparieren und geben es dem Jungen."], "answer": 2, "ref": [2, 3, 4, 5, 6], "explain": "Die Zusammenfassung nennt die Suche mit Hinweisen, die Reparatur und den Fund für den Jungen.", "hint": "Eine Zusammenfassung darf keine Ereignisse erfinden."}, {"type": "own", "skill": "Mit eigenen Worten antworten", "title": "Erkläre in zwei bis drei Sätzen: Warum lassen Minka und Fuji das Buch reparieren?", "ref": [4], "model": "Die Seite ist eingerissen. Fuji befürchtet, dass der Riss größer wird und ein Teil der Geschichte fehlt. Deshalb bringen sie das Buch zu Frau Weber, die den Riss repariert (Absatz 4).", "checks": ["Ich nenne den Schaden.", "Ich erkläre, was ohne Reparatur passieren könnte.", "Ich nenne den passenden Absatz."], "steps": ["Nenne zuerst den Schaden.", "Erkläre Fujis Sorge.", "Beschreibe, was die beiden deshalb tun."]}, {"type": "own", "skill": "Mit eigenen Worten antworten", "title": "Welche Hinweise führen zum richtigen Buch? Nenne drei und erkläre, warum die Farbe allein nicht genügt.", "ref": [2, 3], "model": "Die Hinweise sind der grüne Einband, der Fuchs im Titel und der kleine Stern auf der ersten Seite (Absätze 2 und 3). Die Farbe allein reicht nicht, weil vier Bücher einen grünen Einband haben. Die zusätzlichen Hinweise unterscheiden das gesuchte Buch von den anderen.", "checks": ["Ich nenne drei unterschiedliche Hinweise.", "Ich erkläre das Problem mit der Farbe allein.", "Ich belege meine Antwort mit Absätzen."], "steps": ["Suche die Hinweise auf dem Zettel und im gefundenen Buch.", "Nenne drei Merkmale.", "Erkläre, warum weitere Merkmale gebraucht werden."]}]}, {"id": "theatre", "title": "Der Zauberer hinter dem Vorhang", "level": "Aufbau · Erste Vermutungen überprüfen", "paragraphs": ["Am späten Nachmittag gingen Minka und Fuji über den Dorfplatz. Vor dem kleinen Theater stand ein Schild: „Vorstellung um 18 Uhr“. Eine Frau in einer roten Weste hängte Papiersterne neben den Eingang. Aus dem Gebäude hörten die beiden ein dumpfes Poltern. Minka blieb stehen. „Da ist etwas umgefallen“, sagte sie.", "Durch die offene Tür sahen sie einen Mann, der eine große Kiste über die Bühne schob. Sobald er sie absetzte, polterte es wieder. „Das Geräusch kommt von der Kiste“, sagte Fuji. Doch Minka hatte inzwischen eine schmale Gestalt hinter dem Vorhang entdeckt. Sie trug einen spitzen Hut und rührte sich nicht.", "„Ein Zauberer!“, flüsterte Minka. Fuji trat neben sie. Eine Schnur führte vom Hut bis zu einem Holzgestell. Die Gestalt hatte bemalte Holzhände. „Das ist wahrscheinlich eine Puppe“, sagte er. Da zog jemand hinter dem Gestell an einer Schnur. Die rechte Hand der Gestalt hob sich langsam.", "Die Frau mit der roten Weste kam hinzu. „Das ist unser Zauberer für das Puppenspiel“, erklärte sie. „Die Puppenspielerin bewegt ihn mit Schnüren. Vor der Vorstellung prüfen wir jede Bewegung.“ Minka betrachtete die Hände genauer. Nun erkannte sie kleine Gelenke aus Metall.", "Der Mann auf der Bühne suchte unterdessen seinen Hammer. „Eben lag er noch auf der Kiste“, murmelte er. Fuji sah neben der Kiste ein rotes Band. Daran hing der Hammer, der beim Schieben hinter die Kiste gefallen war. Fuji zeigte mit der Nase auf die Stelle. Der Mann holte ihn hervor und bedankte sich.", "Als die Theaterglocke läutete, gingen die beiden wieder auf den Dorfplatz. „Ich habe zuerst nur den Hut gesehen“, sagte Minka. „Darum dachte ich an einen echten Zauberer.“ Fuji schaute zurück zum Theater. Hinter dem Vorhang konnte man noch einmal die Holzhand sehen. Diesmal winkte Minka der Puppe zu."], "questions": [{"type": "choice", "skill": "Informationen finden", "title": "Wann beginnt die Vorstellung laut Schild?", "choices": ["Am nächsten Morgen.", "Um 18 Uhr.", "Um 16 Uhr."], "answer": 1, "ref": [1], "explain": "Die Zeit steht auf dem Schild vor dem Theater.", "hint": "Suche die Zahl auf dem Schild."}, {"type": "choice", "skill": "Ursachen erklären", "title": "Was verursacht das dumpfe Poltern?", "choices": ["Die Theaterglocke.", "Minkas Schritte.", "Der Mann setzt die große Kiste ab."], "answer": 2, "ref": [2], "explain": "Jedes Absetzen der Kiste verursacht das Geräusch.", "hint": "Die beiden beobachten, wann das Poltern wieder zu hören ist."}, {"type": "choice", "skill": "Wörter aus dem Zusammenhang verstehen", "title": "Was bedeutet „rührte sich nicht“ in Absatz 2?", "choices": ["Die Gestalt bewegte sich nicht.", "Die Gestalt kochte etwas.", "Die Gestalt lief zur Tür."], "answer": 0, "ref": [2, 3], "explain": "Die Gestalt bleibt zunächst unbeweglich. Erst beim Ziehen an der Schnur hebt sich ihre Hand.", "hint": "Vergleiche die Gestalt vor und nach dem Ziehen an der Schnur."}, {"type": "choice", "skill": "Informationen finden", "title": "Welche Farbe hat die Weste der Frau?", "choices": ["Blau.", "Rot.", "Grün."], "answer": 1, "ref": [1, 4], "explain": "Die Frau trägt eine rote Weste.", "hint": "Suche die Beschreibung ihrer Kleidung."}, {"type": "choice", "skill": "Vermutungen mit Hinweisen prüfen", "title": "Welcher Hinweis spricht dafür, dass die Gestalt eine Puppe ist?", "choices": ["Sie trägt einen spitzen Hut.", "Sie steht hinter einem Vorhang.", "Sie hat bemalte Holzhände und Schnüre."], "answer": 2, "ref": [3], "explain": "Holzhände und Schnüre passen zu einer Puppe. Ein Hut allein könnte auch zu einem Menschen gehören.", "hint": "Welches Merkmal erklärt, wie die Gestalt bewegt wird?"}, {"type": "choice", "skill": "Bezüge verstehen", "title": "In Absatz 4 steht: „Die Puppenspielerin bewegt ihn mit Schnüren.“ Wer ist mit „ihn“ gemeint?", "choices": ["Der Zauberer als Puppe.", "Der Mann mit der Kiste.", "Fuji."], "answer": 0, "ref": [4], "explain": "Die Frau beschreibt, wie die Zaubererpuppe bewegt wird.", "hint": "Der Satz erklärt das Puppenspiel."}, {"type": "choice", "skill": "Aussagen prüfen", "title": "„Die Puppe hebt von allein die Hand, ohne dass jemand etwas tut.“ Welche Antwort passt?", "choices": ["Das steht im Text.", "Das widerspricht dem Text.", "Dazu gibt es keine Information."], "answer": 1, "ref": [3, 4], "explain": "Jemand zieht an einer Schnur. Die Puppenspielerin bewegt die Puppe.", "hint": "Suche, welche Handlung die Bewegung auslöst."}, {"type": "order", "skill": "Ereignisse ordnen", "title": "Was geschieht zuerst? Ordne die vier Ereignisse.", "items": ["Fuji entdeckt den Hammer hinter der Kiste.", "Minka hört ein Poltern.", "Die Frau erklärt das Puppenspiel.", "Minka hält die Gestalt für einen Zauberer."], "answer": [1, 3, 2, 0], "ref": [1, 3, 4, 5], "explain": "Die Ereignisse stehen nun so wie in der Geschichte: vom ersten bis zum letzten.", "hint": "Suche das Ereignis am Anfang. Was geschieht erst danach?"}, {"type": "choice", "skill": "Informationen finden", "title": "Wo liegt der gesuchte Hammer?", "choices": ["Unter dem Dorfplatzschild.", "In der Hand der Puppe.", "Hinter der großen Kiste."], "answer": 2, "ref": [5], "explain": "Der Hammer ist beim Schieben hinter die Kiste gefallen.", "hint": "Das rote Band führt Fuji zum gesuchten Gegenstand."}, {"type": "choice", "skill": "Die ganze Geschichte verstehen", "title": "Was lernt Minka bei der Entdeckung der Puppe?", "choices": ["Man sollte mehrere Hinweise prüfen, bevor man eine erste Vermutung für sicher hält.", "Jeder spitze Hut gehört einem echten Zauberer.", "Eine Puppe kann nie bewegt werden."], "answer": 0, "ref": [3, 4, 6], "explain": "Minka sieht zunächst nur den Hut. Weitere Hinweise und die Erklärung zeigen, dass es eine Puppe ist.", "hint": "Vergleiche ihre erste Vermutung mit dem, was sie später erkennt."}, {"type": "own", "skill": "Mit eigenen Worten antworten", "title": "Warum hält Minka die Gestalt zuerst für einen Zauberer? Erkläre auch, wodurch sie ihre Meinung ändert.", "ref": [3, 4, 6], "model": "Der spitze Hut lässt Minka zuerst an einen Zauberer denken (Absätze 3 und 6). Später erklärt die Frau, dass es eine Puppe ist. Minka sieht außerdem die kleinen Metallgelenke (Absatz 4). Diese Hinweise verändern ihre Einschätzung.", "checks": ["Ich erkläre Minkas erste Vermutung.", "Ich nenne eine Erklärung oder Beobachtung, die sie korrigiert.", "Ich nenne die passenden Absätze."], "steps": ["Beginne mit dem Merkmal, das Minka zuerst sieht.", "Nenne einen späteren Hinweis auf eine Puppe.", "Erkläre, wie sich dadurch ihre Meinung verändert."]}, {"type": "own", "skill": "Mit eigenen Worten antworten", "title": "Fuji beobachtet genau. Belege das mit zwei verschiedenen Entdeckungen aus der Geschichte.", "ref": [3, 5], "model": "Fuji bemerkt die Schnur und die bemalten Holzhände und vermutet deshalb eine Puppe (Absatz 3). Außerdem entdeckt er das rote Band und den Hammer hinter der Kiste (Absatz 5). Beide Entdeckungen zeigen, dass er auf Einzelheiten achtet.", "checks": ["Ich nenne zwei unterschiedliche Entdeckungen.", "Ich erkläre, was jede Entdeckung zeigt.", "Ich nenne zu beiden die Absatznummer."], "steps": ["Suche eine Entdeckung an der Gestalt.", "Suche eine weitere Entdeckung bei der Kiste.", "Verbinde beide mit der Aussage über Fujis genaues Beobachten."]}]}, {"id": "trail", "title": "Der sichere Umweg", "level": "Vertiefung · Entscheidungen und Veränderungen erklären", "paragraphs": ["Am Sonntag wollten Minka und Fuji mit ihrer Nachbarin Lena zum Aussichtshügel gehen. Lena packte eine Flasche Wasser und eine Karte in ihren Rucksack. Am Waldweg standen zwei Wegweiser: „Hügel – kurzer Weg“ und „Hügel – Bachweg“. Der kurze Weg führte steil bergauf. Der Bachweg verlief zuerst am Wasser entlang.", "Minka zeigte auf den kurzen Weg. „Dann sind wir schneller oben.“ Lena sah die dunklen Wolken an. „Nach dem Regen von gestern könnte der steile Weg rutschig sein“, sagte sie. Fuji schnupperte am Boden. Der Lehm klebte an seinen Pfoten. Gemeinsam entschieden sie sich für den längeren Bachweg.", "Nach einer Weile erreichten sie eine kleine Holzbrücke. Ein rotes Absperrband hing zwischen zwei Pfosten. Daneben stand: „Brücke beschädigt. Bitte Umleitung benutzen.“ Minka konnte durch einen Spalt eine lose Planke sehen. Lena hielt Abstand zur Brücke und faltete ihre Karte auseinander.", "Auf der Karte verlief ein anderer Weg weiter bachabwärts zu einer Steinbrücke. Ein gelbes Schild mit der Aufschrift „Umleitung“ zeigte in dieselbe Richtung. „Wir bleiben auf dem markierten Weg“, sagte Lena. Sie gingen am Bach entlang. Bald sahen sie die Steinbrücke zwischen den Bäumen.", "Nach dem Überqueren der Steinbrücke führte der Weg in einer weiten Kurve zum Aussichtshügel. Als die drei oben ankamen, riss die Wolkendecke auf. Zwischen den Bäumen sahen sie das Dorf und den See. Minka setzte sich neben Fuji. „Wir haben länger gebraucht“, sagte sie, „aber jetzt sind wir sicher hier.“", "Für den Rückweg suchte Lena auf der Karte wieder den Weg über die Steinbrücke. Minka widersprach diesmal nicht. Fuji trank aus dem mitgebrachten Wassernapf. Erst dann machten sie sich auf den Heimweg. Die beschädigte Holzbrücke blieb hinter dem Absperrband."], "questions": [{"type": "choice", "skill": "Informationen finden", "title": "Was packt Lena am Anfang in ihren Rucksack?", "choices": ["Ein Absperrband und einen Hammer.", "Eine Flasche Wasser und eine Karte.", "Einen roten Ball und ein Buch."], "answer": 1, "ref": [1], "explain": "Wasserflasche und Karte werden ausdrücklich genannt.", "hint": "Suche die Gegenstände vor dem Beginn der Wanderung."}, {"type": "choice", "skill": "Informationen finden", "title": "Warum möchte Minka zuerst den kurzen Weg nehmen?", "choices": ["Sie will die Holzbrücke reparieren.", "Sie möchte am Bach spielen.", "Sie möchte schneller oben sein."], "answer": 2, "ref": [2], "explain": "Minka begründet ihren Vorschlag damit, schneller auf dem Hügel zu sein.", "hint": "Lies Minkas wörtliche Rede zum kurzen Weg."}, {"type": "choice", "skill": "Wörter aus dem Zusammenhang verstehen", "title": "Was bedeutet „Umleitung“ hier?", "choices": ["Ein anderer Weg, weil der bisherige nicht benutzt werden soll.", "Eine Abkürzung über die beschädigte Brücke.", "Eine Pause am Ziel."], "answer": 0, "ref": [3, 4], "explain": "Die beschädigte Brücke wird umgangen. Der andere Weg führt zur Steinbrücke.", "hint": "Warum kann der geplante Weg an der Holzbrücke nicht weitergehen?"}, {"type": "choice", "skill": "Ursachen erklären", "title": "Warum wählen die drei zunächst den längeren Bachweg?", "choices": ["Er führt laut Text ohne jede Brücke zum Ziel.", "Der steile kurze Weg könnte nach dem Regen rutschig sein.", "Der kurze Weg ist ausdrücklich gesperrt."], "answer": 1, "ref": [2], "explain": "Lena vermutet Rutschgefahr. Der klebrige Lehm ist ein zusätzlicher Hinweis auf den nassen Boden.", "hint": "Der kurze Weg ist nicht gesperrt; welche Gefahr nennt Lena?"}, {"type": "choice", "skill": "Informationen finden", "title": "Was entdeckt Minka an der Holzbrücke?", "choices": ["Eine goldene Marke.", "Eine neue Lampe.", "Eine lose Planke."], "answer": 2, "ref": [3], "explain": "Durch einen Spalt sieht Minka eine lose Planke.", "hint": "Suche ihre Beobachtung hinter dem Absperrband."}, {"type": "choice", "skill": "Bezüge verstehen", "title": "In Absatz 4 steht: „in dieselbe Richtung“. Welche Richtung ist gemeint?", "choices": ["Bachabwärts zur Steinbrücke, wie auf der Karte.", "Zurück zum Dorf, wie auf dem ersten Wegweiser.", "Direkt über die gesperrte Holzbrücke."], "answer": 0, "ref": [4], "explain": "Karte und gelbes Umleitungsschild weisen beide zur Steinbrücke bachabwärts.", "hint": "Vergleiche die Karte mit dem gelben Schild."}, {"type": "choice", "skill": "Aussagen prüfen", "title": "„Die drei überqueren die beschädigte Holzbrücke.“ Welche Antwort passt?", "choices": ["Das steht im Text.", "Das widerspricht dem Text.", "Der Text nennt keine benutzte Brücke."], "answer": 1, "ref": [4, 5], "explain": "Die drei folgen der Umleitung und überqueren die Steinbrücke.", "hint": "Unterscheide die beiden Brücken."}, {"type": "order", "skill": "Ereignisse ordnen", "title": "Was geschieht zuerst? Ordne die vier Ereignisse.", "items": ["Die drei kommen auf dem Hügel an.", "Sie wählen den Bachweg.", "Sie überqueren die Steinbrücke.", "Sie entdecken das Absperrband an der Holzbrücke."], "answer": [1, 3, 2, 0], "ref": [2, 3, 4, 5], "explain": "Die Ereignisse stehen nun so wie in der Geschichte: vom ersten bis zum letzten.", "hint": "Suche das Ereignis am Anfang. Was geschieht erst danach?"}, {"type": "choice", "skill": "Gefühle und Absichten verstehen", "title": "Warum widerspricht Minka beim Rückweg nicht mehr?", "choices": ["Sie hat den Weg vergessen.", "Sie darf laut Text nichts mehr sagen.", "Sie hat gesehen, dass der sichere Umweg sie zum Ziel gebracht hat."], "answer": 2, "ref": [5, 6], "explain": "Ihre Aussage „sicher hier“ und ihr Verhalten beim Rückweg passen dazu, dass sie die sichere Route akzeptiert.", "hint": "Verbinde Minkas Aussage auf dem Hügel mit ihrem Verhalten beim Rückweg."}, {"type": "choice", "skill": "Die ganze Geschichte verstehen", "title": "Welche Überschrift passt ebenfalls?", "choices": ["Ein sicherer Umweg zum Ziel", "Minka repariert die Holzbrücke", "Der verlorene Rucksack"], "answer": 0, "ref": [2, 3, 4, 5], "explain": "Die Wahl sicherer Wege und der Umweg zur Steinbrücke bestimmen die Handlung.", "hint": "Suche eine Überschrift, die das wichtige Problem und die Lösung verbindet."}, {"type": "own", "skill": "Mit eigenen Worten antworten", "title": "Nenne zwei verschiedene Gründe, warum die drei ihre Wege ändern. Belege beide mit dem Text.", "ref": [2, 3], "model": "Zuerst wählen sie den Bachweg, weil der steile kurze Weg nach dem Regen rutschig sein könnte (Absatz 2). Später nehmen sie die Umleitung zur Steinbrücke, weil die Holzbrücke beschädigt ist (Absatz 3).", "checks": ["Ich nenne den Grund für die erste Wegwahl.", "Ich nenne den Grund für die spätere Umleitung.", "Ich belege beide Gründe mit Absatznummern."], "steps": ["Betrachte zuerst die Entscheidung an den Wegweisern.", "Betrachte danach die Entscheidung an der Holzbrücke.", "Formuliere zwei verschiedene Gründe."]}, {"type": "own", "skill": "Mit eigenen Worten antworten", "title": "Minka denkt am Anfang anders über die Wegwahl als am Ende. Erkläre die Veränderung.", "ref": [2, 5, 6], "model": "Am Anfang möchte Minka möglichst schnell zum Hügel kommen (Absatz 2). Oben betont sie, dass sie trotz des längeren Weges sicher angekommen sind (Absatz 5). Beim Rückweg akzeptiert sie den Weg über die Steinbrücke (Absatz 6). Sicherheit ist ihr nun wichtiger als die kürzeste Strecke.", "checks": ["Ich beschreibe ihren Wunsch am Anfang.", "Ich beschreibe ihre Haltung am Ende.", "Ich erkläre die Veränderung mit passenden Textbelegen."], "steps": ["Beginne: „Am Anfang möchte Minka …“", "Vergleiche damit ihre Aussage auf dem Hügel.", "Erkläre, was sie aus dem Weg zum Ziel gelernt hat."]}]}]);
